//! Optional local legacy-office conversion. This module never edits a note or
//! calls an existing desktop Office session. Every run owns a new working
//! directory and returns the exact original, intermediate and generated bytes.
//! Ordinary DOCX conversion has no dependency on this module's host software.
use crate::owned_process::{Command, Stdio};
use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};
use std::{
    fs::{self, OpenOptions},
    io::{Read, Write},
    path::{Path, PathBuf},
    sync::{
        Arc,
        atomic::{AtomicBool, Ordering},
    },
    time::Duration,
};
use weftext_core::{CoreErrorDetails, ErrorDetailGroup};
use weftext_messages::{DiagnosticOrigin, ErrorDescription, RawDiagnostic, UiMessage};

const MAX_BYTES: usize = 64 * 1024 * 1024;
const TIMEOUT: Duration = Duration::from_secs(90);
const OLE_MAGIC: &[u8] = b"\xd0\xcf\x11\xe0\xa1\xb1\x1a\xe1";

pub(crate) struct ConversionLocation {
    pub(crate) root: PathBuf,
    pub(crate) request_id: String,
}
/// Keep private actor stages in their original namespace, but avoid expanding
/// that namespace into the native application's working/profile paths. The
/// opaque ID retains 122 SHA-256 bits after UUID version/variant bits are set.
pub(crate) fn scoped_location(
    base: &Path,
    deployment: &str,
    library_root: &Path,
    actor: &str,
    actor_epoch: u64,
    user_operation_id: &str,
    purpose: &str,
) -> Result<ConversionLocation, LegacyError> {
    let id = uuid::Uuid::parse_str(user_operation_id).map_err(|cause| {
        error(
            "requestId",
            UiMessage::error_api_legacy_office_canonical_v4_operation_required(),
        )
        .diagnostic(DiagnosticOrigin::Dependency, cause.to_string())
    })?;
    if !base.is_absolute()
        || id.to_string() != user_operation_id
        || id.get_version() != Some(uuid::Version::Random)
        || !matches!(purpose, "export" | "import")
    {
        return Err(error(
            "conversionScope",
            UiMessage::error_api_legacy_office_conversion_scope_invalid(),
        ));
    }
    let scope = serde_json::json!({"schemaVersion":1,"deployment":deployment,"libraryRoot":library_root,"actor":actor,"actorEpoch":actor_epoch,"userOperationId":user_operation_id,"purpose":purpose});
    let hash = Sha256::digest(scope.to_string().as_bytes());
    let mut bytes = [0u8; 16];
    bytes.copy_from_slice(&hash[..16]);
    bytes[6] = (bytes[6] & 0x0f) | 0x40;
    bytes[8] = (bytes[8] & 0x3f) | 0x80;
    Ok(ConversionLocation {
        root: base.join("runs"),
        request_id: uuid::Uuid::from_bytes(bytes).to_string(),
    })
}

fn execution_path_budget(workspace: &Path, backend: &str) -> Result<(), LegacyError> {
    #[cfg(windows)]
    {
        use std::os::windows::ffi::OsStrExt;
        let units: Vec<u16> = workspace.as_os_str().encode_wide().collect();
        let prefix: Vec<u16> = r"\\?\".encode_utf16().collect();
        let unc: Vec<u16> = r"\\?\UNC\".encode_utf16().collect();
        let length = if units.starts_with(&unc) {
            units.len() - unc.len() + 2
        } else if units.starts_with(&prefix) {
            units.len() - prefix.len()
        } else {
            units.len()
        };
        // CreateProcess rejects a >MAX_PATH current directory even with a
        // verbatim prefix. This installed Writer also crashes in first-profile
        // initialization at 191 native units; 120/125/127-unit owned workspaces
        // were verified. Use that conservative envelope, not an inferred claim
        // that every internal Writer file supports Windows long paths.
        let limit = if backend == "libreoffice" { 128 } else { 240 };
        if length > limit {
            return Err(error(
                "executionPathTooLong",
                UiMessage::error_api_legacy_office_execution_path_budget(
                    weftext_messages::params::ErrorApiLegacyOfficeExecutionPathBudget {
                        limit: weftext_messages::UiInteger::new(limit as i64)
                            .expect("a fixed backend path budget is a safe message integer"),
                    },
                ),
            ));
        }
    }
    #[cfg(not(windows))]
    {
        let _ = (workspace, backend);
    }
    Ok(())
}

#[derive(Clone, Copy, Debug, Deserialize, Serialize, PartialEq, Eq)]
#[serde(rename_all = "camelCase")]
pub(crate) enum Direction {
    DocToDocx,
    DocxToDoc,
    WpsToDocx,
    DocxToWps,
}
impl Direction {
    fn extensions(self) -> (&'static str, &'static str) {
        match self {
            Self::DocToDocx => ("doc", "docx"),
            Self::DocxToDoc => ("docx", "doc"),
            Self::WpsToDocx => ("wps", "docx"),
            Self::DocxToWps => ("docx", "wps"),
        }
    }
    fn is_import(self) -> bool {
        matches!(self, Self::DocToDocx | Self::WpsToDocx)
    }
    fn involves_native_wps(self) -> bool {
        matches!(self, Self::WpsToDocx | Self::DocxToWps)
    }
}

#[derive(Debug, Clone, Serialize)]
#[serde(rename_all = "camelCase")]
pub(crate) struct DirectionCapability {
    pub(crate) direction: Direction,
    pub(crate) available: bool,
    /// This is deliberately false: discovering a software version or a filter
    /// is not a real-host content/review round-trip acceptance result.
    pub(crate) content_roundtrip_verified: bool,
    #[serde(flatten)]
    pub(crate) description: ErrorDescription,
}

