    #[test]
    fn returning_success_without_expected_output_cannot_succeed() {
        let temp = tempfile::tempdir().unwrap();
        assert_eq!(
            read_generated(&temp.path().join("missing.docx"), "docx", temp.path())
                .unwrap_err()
                .code,
            "outputMissing"
        );
        let path = temp.path().join("wrong.doc");
        fs::write(&path, b"PK\x03\x04not a binary doc").unwrap();
        assert_eq!(
            read_generated(&path, "doc", temp.path()).unwrap_err().code,
            "outputFormat"
        );
        let other = tempfile::tempdir().unwrap();
        let outside = other.path().join("outside.doc");
        fs::write(&outside, OLE_MAGIC).unwrap();
        assert_eq!(
            read_generated(&outside, "doc", temp.path())
                .unwrap_err()
                .code,
            "outputInvalid"
        );
    }

    #[test]
