    #[test]
    fn native_wps_rejects_renamed_docx_doc_and_unproven_formats() {
        assert_eq!(
            validate_native_wps(b"PK\x03\x04member word/document.xml payload")
                .unwrap_err()
                .code,
            "wpsRenamedDocx"
        );
        let mut doc = vec![0u8; 1024];
        doc[..8].copy_from_slice(OLE_MAGIC);
        let name: Vec<u8> = "WordDocument\0"
            .encode_utf16()
            .flat_map(u16::to_le_bytes)
            .collect();
        doc[512..512 + name.len()].copy_from_slice(&name);
        doc[512 + 64..512 + 66].copy_from_slice(&(name.len() as u16).to_le_bytes());
        doc[512 + 66] = 2;
        assert_eq!(validate_native_wps(&doc).unwrap_err().code, "wpsRenamedDoc");
        assert_eq!(
            validate_native_wps(b"unproven format").unwrap_err().code,
            "nativeWpsUnverified"
        );
        let temp = tempfile::tempdir().unwrap();
        let path = temp.path().join("renamed.wps");
        fs::write(&path, b"PK\x03\x04member word/document.xml payload").unwrap();
        assert_eq!(
            read_generated(&path, "wps", temp.path()).unwrap_err().code,
            "wpsRenamedDocx"
        );
    }

